H.background();
const w = H.W, hh = H.H;
const a = P.a, b = P.b, c = P.c, d = P.d;
const A = [[a, b], [1, 2]];
const B = [[c, 0], [1, d]];
const C = [
  [A[0][0] * B[0][0] + A[0][1] * B[1][0], A[0][0] * B[0][1] + A[0][1] * B[1][1]],
  [A[1][0] * B[0][0] + A[1][1] * B[1][0], A[1][0] * B[0][1] + A[1][1] * B[1][1]]
];
const cell = Math.floor((t / 0.9) % 4);
const hr = cell < 2 ? 0 : 1;
const hc = cell % 2;
const cw = 44, ch = 34;
function drawMat(M, x, y, label, hiRow, hiCol) {
  H.rect(x - 8, y - 24, cw * 2 + 16, ch * 2 + 8, { stroke: H.colors.grid, width: 2, radius: 8 });
  H.text(label, x - 6, y - 32, { color: H.colors.ink, size: 15, weight: 700 });
  for (let r = 0; r < 2; r++) for (let cc = 0; cc < 2; cc++) {
    const lit = (hiRow === r && hiCol === -1) || (hiCol === cc && hiRow === -1) || (hiRow === r && hiCol === cc);
    H.text(M[r][cc].toFixed(1), x + cc * cw + 14, y + r * ch + 6, { color: lit ? H.colors.warn : H.colors.sub, size: 16, align: "center" });
  }
}
const baseY = hh * 0.40;
drawMat(A, w * 0.06, baseY, "A (row)", hr, -1);
drawMat(B, w * 0.34, baseY, "B (col)", -1, hc);
H.text("=", w * 0.60, baseY + 18, { color: H.colors.ink, size: 26, weight: 700 });
drawMat(C, w * 0.68, baseY, "A*B", hr, hc);
const px = w * 0.68 + hc * cw + 14, py = baseY + hr * ch + 6;
H.circle(px, py - 5, 12 + 3 * Math.sin(t * 4), { stroke: H.colors.good, width: 2 });
H.text("Matrix multiplication: row dot column", 24, 30, { color: H.colors.ink, size: 18, weight: 700 });
const prod = A[hr][0] * B[0][hc] + A[hr][1] * B[1][hc];
H.text("C[" + (hr + 1) + "][" + (hc + 1) + "] = " + A[hr][0].toFixed(1) + "*" + B[0][hc].toFixed(1) + " + " + A[hr][1].toFixed(1) + "*" + B[1][hc].toFixed(1) + " = " + prod.toFixed(1),
  24, 52, { color: H.colors.sub, size: 13 });
H.legend([{ label: "row of A", color: H.colors.warn }, { label: "active cell", color: H.colors.good }], w - 160, 28);
